SET @catalog_conflicts = @catalog_conflicts + (SELECT COUNT(*) FROM product_images WHERE product_id=(SELECT p.id FROM products p WHERE p.sku='CAT-FG-FER-PUP') AND image_url=(SELECT CONCAT('/manga-store/backend/public/uploads/products/',p.id,'/be7d916dbd9684635f382890c51e9117.jpg') FROM products p WHERE p.sku='CAT-FG-FER-PUP') AND NOT ((alt_vi <=> 'Fern – POP UP PARADE – góc chụp 3') AND (alt_en <=> 'Fern – POP UP PARADE – view 3') AND (sort_order <=> 20) AND (is_primary <=> 0)));
SET @catalog_conflicts = @catalog_conflicts + (SELECT COUNT(*) FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN manga_series s ON s.id=p.series_id WHERE (p.sku='CAT-FG-HIT-PUP' OR p.slug='hitori-gotoh-pop-up-parade') AND NOT ((BINARY p.sku <=> BINARY 'CAT-FG-HIT-PUP') AND (BINARY p.slug <=> BINARY 'hitori-gotoh-pop-up-parade') AND (BINARY p.name_vi <=> BINARY 'Hitori Gotoh – POP UP PARADE') AND (BINARY p.name_en <=> BINARY 'Hitori Gotoh – POP UP PARADE') AND (BINARY p.description_vi <=> BINARY 'Mẫu POP UP PARADE của Hitori Gotoh trong Bocchi the Rock!, do Good Smile Company sản xuất. Figure không theo tỉ lệ, cao khoảng 195 mm; phù hợp trưng bày cùng bộ sưu tập anime. Ảnh quảng bá chính thức có thể là mẫu thử và khác đôi chút so với sản phẩm bán lẻ. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.') AND (BINARY p.description_en <=> BINARY 'Hitori Gotoh from Bocchi the Rock!, in the specific POP UP PARADE release manufactured by Good Smile Company. This non-scale figure stands approximately 195 mm tall. Official promotional photographs may show prototypes and can differ from retail production. Price and stock are simulated for a course project, not an official offer.') AND (BINARY p.price_vnd <=> BINARY 900000) AND (BINARY p.sale_price_vnd <=> BINARY NULL) AND (BINARY p.stock_quantity <=> BINARY 6) AND (BINARY p.status <=> BINARY 'active') AND (BINARY p.is_featured <=> BINARY 0) AND (BINARY c.slug <=> BINARY 'figures') AND (BINARY s.slug <=> BINARY 'bocchi-the-rock')));
SET @catalog_conflicts = @catalog_conflicts + (SELECT COUNT(*) FROM product_images WHERE product_id=(SELECT p.id FROM products p WHERE p.sku='CAT-FG-HIT-PUP') AND image_url=(SELECT CONCAT('/manga-store/backend/public/uploads/products/',p.id,'/6dd81e0b1e289f707972c8083acc205e.jpg') FROM products p WHERE p.sku='CAT-FG-HIT-PUP') AND NOT ((alt_vi <=> 'Hitori Gotoh – POP UP PARADE – ảnh chính') AND (alt_en <=> 'Hitori Gotoh – POP UP PARADE – main image') AND (sort_order <=> 0) AND (is_primary <=> 1)));
SET @catalog_conflicts = @catalog_conflicts + (SELECT COUNT(*) FROM product_images i JOIN products p ON p.id=i.product_id WHERE p.sku='CAT-FG-HIT-PUP' AND i.is_primary=1 AND i.image_url<>CONCAT('/manga-store/backend/public/uploads/products/',p.id,'/6dd81e0b1e289f707972c8083acc205e.jpg'));
SET @catalog_conflicts = @catalog_conflicts + (SELECT COUNT(*) FROM product_images WHERE product_id=(SELECT p.id FROM products p WHERE p.sku='CAT-FG-HIT-PUP') AND image_url=(SELECT CONCAT('/manga-store/backend/public/uploads/products/',p.id,'/41084279fe241f34747040723499a067.jpg') FROM products p WHERE p.sku='CAT-FG-HIT-PUP') AND NOT ((alt_vi <=> 'Hitori Gotoh – POP UP PARADE – góc chụp 2') AND (alt_en <=> 'Hitori Gotoh – POP UP PARADE – view 2') AND (sort_order <=> 10) AND (is_primary <=> 0)));
SET @catalog_conflicts = @catalog_conflicts + (SELECT COUNT(*) FROM product_images WHERE product_id=(SELECT p.id FROM products p WHERE p.sku='CAT-FG-HIT-PUP') AND image_url=(SELECT CONCAT('/manga-store/backend/public/uploads/products/',p.id,'/9b6cb7dc7c247b203f7371093ba2dbd3.jpg') FROM products p WHERE p.sku='CAT-FG-HIT-PUP') AND NOT ((alt_vi <=> 'Hitori Gotoh – POP UP PARADE – góc chụp 3') AND (alt_en <=> 'Hitori Gotoh – POP UP PARADE – view 3') AND (sort_order <=> 20) AND (is_primary <=> 0)));
