INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-MG-AOT-EN-01','attack-on-titan-vol-1-kodansha-en','Đại Chiến Titan – Tập 1 (bản tiếng Anh)','Attack on Titan, Vol. 1 (English Edition)','Tập 1 của manga Attack on Titan do Hajime Isayama sáng tác, bản in tiếng Anh Kodansha. Câu chuyện theo chân những người trẻ phải chiến đấu để sinh tồn trước Titan và khám phá bí mật của thế giới sau các bức tường. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','Volume 1 of Hajime Isayama’s Attack on Titan, Kodansha English print edition. Young survivors confront the Titans while questioning the history and protections of their walled world. Price and stock are simulated for a course project, not an official offer.',220000,NULL,15,'active',1 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='manga' AND s.slug='attack-on-titan' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-MG-AOT-EN-01' OR slug='attack-on-titan-vol-1-kodansha-en');
