INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-MG-OP-VI-01','one-piece-tap-1-kim-dong-vi','One Piece – Tập 1 (tiếng Việt)','One Piece, Vol. 1 (Vietnamese Edition)','Tập 1, ấn bản tiếng Việt của NXB Kim Đồng. Tác giả: Eiichiro Oda. Luffy bắt đầu hành trình tìm kho báu One Piece và gặp những người bạn đồng hành trên biển. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','Volume 1, Vietnamese edition published by Kim Dong. Creator: Eiichiro Oda. Luffy pursues the One Piece treasure and meets companions along his seafaring journey. Price and stock are simulated for a course project, not an official offer.',30000,NULL,25,'active',0 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='manga' AND s.slug='one-piece' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-MG-OP-VI-01' OR slug='one-piece-tap-1-kim-dong-vi');
