INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-MG-DOR-VI-01','doraemon-tap-1-kim-dong-vi','Doraemon truyện ngắn – Tập 1 (tiếng Việt)','Doraemon Short Stories, Vol. 1 (Vietnamese Edition)','Tập 1, ấn bản tiếng Việt của NXB Kim Đồng. Tác giả: Fujiko F. Fujio. Doraemon và Nobita khám phá những tình huống đời thường qua các bảo bối tương lai. Những mẩu chuyện kết hợp sự hài hước với tình bạn và trí tưởng tượng. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','Volume 1, Vietnamese edition published by Kim Dong. Creator: Fujiko F. Fujio. Doraemon and Nobita turn everyday problems into imaginative adventures with futuristic gadgets, friendship and gentle humor. Price and stock are simulated for a course project, not an official offer.',25000,NULL,25,'active',0 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='manga' AND s.slug='doraemon' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-MG-DOR-VI-01' OR slug='doraemon-tap-1-kim-dong-vi');
