INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-MG-NAR-VI-01','naruto-tap-1-kim-dong-vi','Naruto – Tập 1 (tiếng Việt)','Naruto, Vol. 1 (Vietnamese Edition)','Tập 1, ấn bản tiếng Việt của NXB Kim Đồng. Tác giả: Masashi Kishimoto. Naruto theo đuổi ước mơ trở thành Hokage và được làng Lá công nhận. Hành trình ninja mở ra những thử thách về tinh thần đồng đội và sự trưởng thành. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','Volume 1, Vietnamese edition published by Kim Dong. Creator: Masashi Kishimoto. Naruto pursues recognition and his ambition to become Hokage. His ninja journey brings challenges of teamwork, responsibility and personal growth. Price and stock are simulated for a course project, not an official offer.',30000,NULL,25,'active',1 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='manga' AND s.slug='naruto' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-MG-NAR-VI-01' OR slug='naruto-tap-1-kim-dong-vi');
