INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-MG-DB-VI-01','dragon-ball-tap-1-kim-dong-vi','Dragon Ball – Bảy Viên Ngọc Rồng – Tập 1 (tiếng Việt)','Dragon Ball, Vol. 1 (Vietnamese Edition)','Tập 1, ấn bản tiếng Việt của NXB Kim Đồng. Tác giả: Akira Toriyama. Goku và Bulma bước vào chuyến phiêu lưu tìm những viên ngọc rồng. Tình bạn, những cuộc chạm trán bất ngờ và tinh thần khám phá tạo nên không khí vui nhộn của bộ truyện. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','Volume 1, Vietnamese edition published by Kim Dong. Creator: Akira Toriyama. Goku and Bulma set out in search of the Dragon Balls. New friendships and unexpected encounters shape this playful adventure. Price and stock are simulated for a course project, not an official offer.',30000,NULL,25,'active',0 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='manga' AND s.slug='dragon-ball' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-MG-DB-VI-01' OR slug='dragon-ball-tap-1-kim-dong-vi');
