INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-NV-YN-VI','your-name-novel-ipm-vi','Your Name. – Tiểu thuyết (tiếng Việt)','Your Name. – Novel (Vietnamese Edition)','Tiểu thuyết do Makoto Shinkai viết, không phải manga hoặc sách tranh phim. Mitsuha và Taki bất ngờ trải nghiệm cuộc sống của nhau qua những lần hoán đổi thân xác. Cuộc gặp gỡ vượt khoảng cách dẫn họ đến một mối liên hệ sâu sắc với ký ức và thời gian. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','A novel written by Makoto Shinkai, not the manga adaptation or a film visual guide. Mitsuha and Taki begin experiencing each other’s lives through unexpected body swaps. Their connection draws them into a story of memory, distance and time. Price and stock are simulated for a course project, not an official offer.',95000,NULL,12,'active',0 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='novels' AND s.slug='your-name' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-NV-YN-VI' OR slug='your-name-novel-ipm-vi');
