INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-NV-WWY-VI','weathering-with-you-novel-ipm-vi','Đứa Con Của Thời Tiết – Tiểu thuyết (tiếng Việt)','Weathering with You – Novel (Vietnamese Edition)','Tiểu thuyết do Makoto Shinkai viết, không phải manga hoặc sách tranh phim. Hodaka đến Tokyo trong những ngày mưa kéo dài và gặp Hina, cô gái có năng lực đặc biệt với bầu trời. Hai người phải đối diện với sự đánh đổi giữa hạnh phúc riêng và những điều lớn hơn bản thân. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','A novel written by Makoto Shinkai, not the manga adaptation or a film visual guide. Hodaka reaches a rain-soaked Tokyo and meets Hina, a girl with a remarkable connection to the sky. Their growing bond raises questions about personal happiness and its wider consequences. Price and stock are simulated for a course project, not an official offer.',95000,85000,12,'active',1 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='novels' AND s.slug='weathering-with-you' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-NV-WWY-VI' OR slug='weathering-with-you-novel-ipm-vi');
