INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-NV-SUZ-VI','suzume-novel-ipm-vi','Khóa Chặt Cửa Nào Suzume – Tiểu thuyết (tiếng Việt)','Suzume – Novel (Vietnamese Edition)','Tiểu thuyết do Makoto Shinkai viết, không phải manga hoặc sách tranh phim. Suzume theo chân một người thanh niên đi đóng những cánh cửa gắn với hiểm họa trên khắp Nhật Bản. Chuyến đi đưa cô trở lại với mất mát, ký ức tuổi thơ và lòng can đảm để tiếp tục sống. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','A novel written by Makoto Shinkai, not the manga adaptation or a film visual guide. Suzume follows a young traveler closing dangerous doors across Japan. Her journey connects an outward adventure with childhood memories, loss and the courage to move forward. Price and stock are simulated for a course project, not an official offer.',145000,NULL,12,'active',0 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='novels' AND s.slug='suzume' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-NV-SUZ-VI' OR slug='suzume-novel-ipm-vi');
