INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-FG-FRI-PUP','frieren-pop-up-parade','Frieren – POP UP PARADE','Frieren – POP UP PARADE','Mẫu POP UP PARADE của Frieren trong Frieren: Beyond Journey’s End, do Good Smile Company sản xuất. Figure không theo tỉ lệ, cao khoảng 160 mm; phù hợp trưng bày cùng bộ sưu tập anime. Ảnh quảng bá chính thức có thể là mẫu thử và khác đôi chút so với sản phẩm bán lẻ. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','Frieren from Frieren: Beyond Journey’s End, in the specific POP UP PARADE release manufactured by Good Smile Company. This non-scale figure stands approximately 160 mm tall. Official promotional photographs may show prototypes and can differ from retail production. Price and stock are simulated for a course project, not an official offer.',850000,NULL,6,'active',0 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='figures' AND s.slug='frieren-beyond-journeys-end' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-FG-FRI-PUP' OR slug='frieren-pop-up-parade');
