INSERT INTO products (category_id,series_id,sku,slug,name_vi,name_en,description_vi,description_en,price_vnd,sale_price_vnd,stock_quantity,status,is_featured) SELECT c.id,s.id,'CAT-FG-MAR-PUP','marin-kitagawa-pop-up-parade','Marin Kitagawa – POP UP PARADE','Marin Kitagawa – POP UP PARADE','Mẫu POP UP PARADE của Marin Kitagawa trong My Dress-Up Darling, do Good Smile Arts Shanghai sản xuất. Figure không theo tỉ lệ, cao khoảng 185 mm; phù hợp trưng bày cùng bộ sưu tập anime. Ảnh quảng bá chính thức có thể là mẫu thử và khác đôi chút so với sản phẩm bán lẻ. Giá và tồn kho minh họa cho đồ án, không phải báo giá chính thức.','Marin Kitagawa from My Dress-Up Darling, in the specific POP UP PARADE release manufactured by Good Smile Arts Shanghai. This non-scale figure stands approximately 185 mm tall. Official promotional photographs may show prototypes and can differ from retail production. Price and stock are simulated for a course project, not an official offer.',900000,850000,6,'active',1 FROM categories c CROSS JOIN manga_series s WHERE @catalog_ready=1 AND c.slug='figures' AND s.slug='my-dress-up-darling' AND NOT EXISTS (SELECT 1 FROM products WHERE sku='CAT-FG-MAR-PUP' OR slug='marin-kitagawa-pop-up-parade');
